'use strict';

// Rounds to a whole number. Tax is charged in whole cents, so taxInCents relies on this.
function round(value) {
  return Math.round(value);
}

// applyDiscount(19.99, 10) should be 17.99: prices keep two decimals.
function applyDiscount(price, percent) {
  return round(price - (price * percent) / 100);
}

function taxInCents(cents, ratePercent) {
  return round((cents * ratePercent) / 100);
}

module.exports = { round, applyDiscount, taxInCents };

